        unordered_map<int, int> freq;
        for (int num : nums) freq[num]++;
        int mostFreq = 0, secMostFreq = 0;
        int freqNum = INT_MAX, secFreqNum = INT_MAX;
        for (auto& [n, f] : freq) {
            if (mostFreq < f) {
                secMostFreq = mostFreq;
                secFreqNum = freqNum;
                mostFreq = f;
                freqNum = n;
            } else if (mostFreq == f) {
                freqNum = min(freqNum, n);
            } else if (secMostFreq < f) {
                secMostFreq = f;
                secFreqNum = n;
            } else if (secMostFreq == f) {
                secFreqNum = min(secFreqNum, n);
            }
        }
        return secMostFreq ? secFreqNum : -1;
    }
};
```

