    int secondMostFrequentElement(vector<int>& nums) {
        int nMax = 0;
        for (int i = 0; i < nums.size(); i++) {
            if (nums[i] > nMax) {
                nMax = nums[i];
            }
        }
        int hashT[nMax + 1] = {0};
        for (int i = 0; i < nums.size(); i++) {
            hashT[nums[i]]++;
        }
        int max = 0, p = 0;
        for (int i = 0; i < (nMax + 1); i++) {
            if (hashT[i] > max) {
                max = hashT[i];
            }
        }

        int max2 = 0;
        for (int i = 0; i < (nMax + 1); i++) {
            if (hashT[i] > max2 && hashT[i] < max) {
                max2 = hashT[i];
                p = i;
            }
        }
        if (max2 == 0) {
            return -1;
        } else {
            return p;
        }
    }
};
